import functools
import os
import subprocess


def run(argv):
    subprocess.run(argv)


def make(n):
    if n <= 0:
        return functools.partial(run, ["pacman", "-S", "r22-cxrec"])
    return functools.partial(make(n - 1))


make(int(os.environ.get("R22_CXREC", "1")))()

